control   = {"소비홈": 10, "대출홈": 60, "카드탭": 30}
treatment = {"소비홈": 28, "대출홈": 45, "카드탭": 27}
print("소비홈 배수:", treatment["소비홈"] / control["소비홈"])  # 2.8
print("전사 합계:", sum(control.values()), sum(treatment.values()))  # 100 100
for k in control:
    print(k, treatment[k] - control[k])  # 18 / -15 / -3

def ltv(arpu, retention, months=12, monthly_discount=0.01):
    total, alive = 0.0, 1.0
    for t in range(months):
        total += alive * arpu / (1 + monthly_discount) ** t
        alive *= retention
    return round(total)

segments = {"서비스 1개": (1_000, 0.70), "서비스 3개 이상": (2_500, 0.92)}
for name, (arpu, ret) in segments.items():
    print(name, ltv(arpu, ret))   # 3218 / 18901
print("배수:", round(ltv(2_500, 0.92) / ltv(1_000, 0.70), 1))  # 5.9
